def shipping(weight, express=False):
    cost = 40
    if weight > 1:
        extra = weight - 1
        import math
        extra = math.ceil(extra)
        i = 0
        while i < extra:
            cost = cost + 10
            i = i + 1
    if express == True:
        cost = cost * 2
    else:
        cost = cost
    return cost
